function qmesCloneWithScreenStyles(source) {
  const clone = source.cloneNode(true);
  const sourceNodes = [source, ...source.querySelectorAll("*")];
  const cloneNodes = [clone, ...clone.querySelectorAll("*")];

  sourceNodes.forEach((node, index) => {
    const clonedNode = cloneNodes[index];
    if (!clonedNode || node.nodeType !== 1) return;

    const computed = window.getComputedStyle(node);
    for (let i = 0; i < computed.length; i += 1) {
      const prop = computed[i];
      try {
        clonedNode.style.setProperty(prop, computed.getPropertyValue(prop), "important");
      } catch (_) {}
    }
  });

  clone.setAttribute("data-qmes-screen-print", "true");
  return clone;
}

function printDoc(sourceEl) {
  /* React onClick이 이벤트 객체를 첫 번째 인자로 넘기는 경우를 방지합니다. */
  const validSource = sourceEl instanceof Element ? sourceEl : null;
  const source = validSource || Array.from(document.querySelectorAll(".doc-paper"))
    .find((el) => el.offsetParent !== null && el.id !== "qmes-label-print-root");
  const printRoot = document.getElementById("qmes-print-root");

  if (!source || !printRoot) {
    alert("인쇄할 성적서 내용을 찾을 수 없습니다.");
    return;
  }

  /* ── 화면 미리보기 = 실제 인쇄 결과 ──
     화면에 렌더링된 계산 스타일(computed style)을 요소별 인라인으로 복제해
     인쇄 전용 CSS 재정의(글자/여백/표 높이 등)의 영향을 완전히 차단하고,
     화면 모습 그대로를 A4에 맞게 비율만 축소하여 출력합니다. */
  const clone = qmesCloneWithScreenStyles(source);
  clone.classList.add("qmes-a4-preview-clone");

  /* 캔버스(QR 등) 내용은 cloneNode로 복사되지 않으므로 비트맵을 직접 복사 */
  const srcCanvases = source.querySelectorAll("canvas");
  const cloneCanvases = clone.querySelectorAll("canvas");
  srcCanvases.forEach((c, i) => {
    const cc = cloneCanvases[i];
    if (!cc) return;
    try {
      cc.width = c.width;
      cc.height = c.height;
      cc.getContext("2d").drawImage(c, 0, 0);
    } catch (_) {}
  });

  /* 인쇄에 불필요한 요소 제거 */
  clone.querySelectorAll("button, .qmes-modal-close, .qmes-print-actions, [data-no-print='true']")
    .forEach((el) => el.remove());

  /* 배경색·표 음영이 미리보기와 동일하게 인쇄되도록 강제 */
  [clone, ...clone.querySelectorAll("*")].forEach((el) => {
    try {
      el.style.setProperty("-webkit-print-color-adjust", "exact", "important");
      el.style.setProperty("print-color-adjust", "exact", "important");
    } catch (_) {}
  });

  /* 화면 크기 측정 후 A4(210×297mm)에 맞는 축소 배율 계산 */
  const rect = source.getBoundingClientRect();
  const MM_TO_PX = 96 / 25.4;
  const PAGE_W = 210 * MM_TO_PX;
  const PAGE_H = 297 * MM_TO_PX;
  const MARGIN = 8 * MM_TO_PX; /* 상하좌우 8mm 여백 */
  const availW = PAGE_W - MARGIN * 2;
  const availH = PAGE_H - MARGIN * 2;
  const scale = Math.min(availW / rect.width, 1);

  /* 복제본을 화면 폭 그대로 두고 zoom으로 축소 → transform과 달리 실제 박스 크기가 줄어들어 인쇄 시 페이지 나눔이 정상 동작함 */
  clone.style.setProperty("width", rect.width + "px", "important");
  clone.style.setProperty("margin", "0", "important");
  clone.style.setProperty("box-shadow", "none", "important");
  clone.style.setProperty("transform", "none", "important");
  clone.style.setProperty("zoom", String(scale), "important");

  const stage = document.createElement("div");
  stage.className = "qmes-screen-print-stage";
  /* 수입·공정·출하검사 성적서 모두 용지 상단에서 1.2cm 추가 하향 배치 */
  const extraTop = (source.classList.contains("qmes-iqc-doc") ||
                    source.classList.contains("qmes-pqc-doc") ||
                    source.classList.contains("qmes-oqc-doc")) ? 12 * MM_TO_PX : 0;
  stage.style.setProperty("width", (rect.width * scale) + "px", "important");
  stage.style.setProperty("height", "auto", "important");
  stage.style.setProperty("margin", (MARGIN + extraTop) + "px auto 0", "important");
  stage.style.setProperty("overflow", "visible", "important");
  stage.appendChild(clone);

  printRoot.innerHTML = "";
  printRoot.appendChild(stage);

  document.body.classList.remove("print-label", "print-doc");
  document.body.classList.add("qmes-screen-exact-print");

  let cleaned = false;
  const cleanup = () => {
    if (cleaned) return;
    cleaned = true;
    document.body.classList.remove("qmes-screen-exact-print");
    printRoot.innerHTML = "";
    window.removeEventListener("afterprint", cleanup);
  };

  window.addEventListener("afterprint", cleanup);
  requestAnimationFrame(() => requestAnimationFrame(() => {
    window.print();
    setTimeout(cleanup, 1500);
  }));
}

/* ──────────────────────────── 통합 데이터 저장소 ──────────────────────────── */
/* 화면 간 연동 + 새로고침 후에도 기록 유지. 실제 서버 구축 시 이 계층만 API로 교체하면 됩니다. */

const DB_KEY = "qmes-local-shipment-dashboard-v8-clean";
const DB_RESET_MARKER = "qmes-shipment-dashboard-clean-reset-v8";

/* 수입검사 개선본 최초 실행 시 기존 테스트 DB를 한 번 초기화합니다.
   이후 입력한 데이터는 새 DB_KEY에 저장되어 새로고침 후에도 유지됩니다. */
try {
  if (!window.localStorage.getItem(DB_RESET_MARKER)) {
    ["qmes-local-v1", "qmes-db-v1", "qmes-local-iqc-v2", "qmes-local-iqc-v3", "qmes-local-iqc-v4-clean", "qmes-local-simple-summary-v5", "qmes-local-title-inline-v6", "qmes-local-title-inline-v7-clean", "qmes-local-shipment-dashboard-v8-clean", DB_KEY].forEach((key) => window.localStorage.removeItem(key));
    window.localStorage.setItem(DB_RESET_MARKER, "1");
  }
} catch (e) { /* 무시 */ }

/* 공용 서버 DB(Supabase) 연결 제거
   - 입력 데이터는 이 브라우저의 localStorage에만 저장됩니다.
   - 외부 서버 전송 및 장치 간 자동 동기화는 수행하지 않습니다. */
function dbDefault() {
  return {
    batches: [], woDocs: {}, iqc: [], iqcMaterials: [], insp: { PQC: [], OQC: [] },
    holds: [], gateEvents: [], intermediateLots: {}, intermediateContainers: {}, materialRemainders: {},
    eqReadings: {}, eqLogs: [], eqAlarms: [], complaints: [], lots: {}, coa: {},
    popEntries: [], auditLogs: [], seqs: {}
  };
}

/* ── 고객사 지적 대응: 실제 저장 단계 품질 게이트 ── */
function qmesText(v) { return String(v ?? "").trim(); }
function qmesActiveHold(lotNo) {
  const lot = qmesText(lotNo);
  return (DB.holds || []).find((h) => {
    const target = qmesText(h.target);
    const status = qmesText(h.status);
    const active = !(status.includes("해제 완료") || status.includes("종결") || status === "완료");
    return active && (target === lot || target.startsWith(lot + " ") || target.startsWith(lot + "("));
  }) || null;
}
function qmesLatestIqc(materialLot) {
  const lot = qmesText(materialLot);
  return (DB.iqc || [])
    .filter((r) => qmesText(r.lot) === lot)
    .sort((a, b) => qmesText(b.inspectedAt || b.recv).localeCompare(qmesText(a.inspectedAt || a.recv)))[0] || null;
}
function qmesMaterialGate(materialLot) {
  const lot = qmesText(materialLot);
  if (!lot) return { ok:false, reason:"원재료 LOT 미입력" };
  const hold = qmesActiveHold(lot);
  if (hold) return { ok:false, reason:`격리·홀드 LOT — ${hold.reason || hold.gate || "사용 차단"}` };
  const iqc = qmesLatestIqc(lot);
  if (!iqc) return { ok:false, reason:"IQC 검사 기록 없음" };
  if (qmesText(iqc.judge) !== "합격") return { ok:false, reason:`IQC ${iqc.judge || "미판정"} — 합격 전 투입 금지` };
  return { ok:true, reason:"IQC 합격" };
}
function qmesPqcPass(lotNo) {
  const rows = (DB.insp?.PQC || []).filter((r) => qmesText(r.lot) === qmesText(lotNo));
  if (!rows.length) return false;
  const latestGroup = qmesText(rows[0].groupId || rows[0].id).replace(/-\d+$/, "");
  const groupRows = rows.filter((r) => qmesText(r.groupId || r.id).replace(/-\d+$/, "") === latestGroup);
  return groupRows.length > 0 && groupRows.every((r) => qmesText(r.judge) === "합격");
}
function qmesProductionComplete(lotNo) {
  const doc = DB.woDocs?.[lotNo];
  return !!doc && (qmesText(doc.status) === "완료" || qmesText(doc.manualStatus) === "완료");
}
function qmesShipmentGate(lotNo) {
  const lot = qmesText(lotNo);
  const hold = qmesActiveHold(lot);
  if (hold) return { ok:false, reason:`홀드 미해제 — ${hold.reason || hold.gate || "출하 차단"}` };
  if (!qmesProductionComplete(lot)) return { ok:false, reason:"생산실적 미완료" };
  if (!qmesPqcPass(lot)) return { ok:false, reason:"PQC 합격 기록 없음" };
  return { ok:true, reason:"출하검사 진행 가능" };
}
function qmesRecordGateBlock(gate, lotNo, reason) {
  DB.gateEvents = [{
    id:`GATE-${Date.now()}`, gate, lot:qmesText(lotNo), reason:qmesText(reason),
    status:"차단", by:window.__QMES_USER__ || "현재 사용자", at:new Date().toISOString()
  }, ...(DB.gateEvents || [])].slice(0, 1000);
  auditLog("품질게이트", "차단", qmesText(lotNo), `${gate} / ${reason}`);
}
let DB = (() => {
  try {
    const current = window.localStorage.getItem(DB_KEY);
    if (current) return { ...dbDefault(), ...JSON.parse(current) };
  } catch (e) { /* 무시 */ }
  return dbDefault();
})();

function auditLog(module, action, target, reason = "") {
  const now = new Date();
  DB.auditLogs = [{
    id: `AUD-${Date.now()}`, module, action, target, reason,
    by: (window.__QMES_USER__ || "현재 사용자"),
    at: now.toLocaleString("ko-KR", { hour12: false })
  }, ...(DB.auditLogs || [])].slice(0, 500);
}

function askDeleteReason(label) {
  const reason = window.prompt(`${label} 삭제 사유를 입력하세요.\n※ 삭제 이력은 감사 로그에 남습니다.`);
  if (reason === null) return null;
  if (!reason.trim()) { window.alert("삭제 사유를 입력해야 합니다."); return null; }
  return reason.trim();
}

function dbSave() {
  try { window.localStorage.setItem(DB_KEY, JSON.stringify(DB)); } catch (e) { /* 무시 */ }
}
function dbReset() {
  DB = dbDefault();
  try { window.localStorage.setItem(DB_KEY, JSON.stringify(DB)); } catch (e) { /* 무시 */ }
}


function downloadQmesBackup() {
  const payload = {
    format: "QMES_BACKUP_V1",
    exportedAt: new Date().toISOString(),
    data: DB,
    users: (() => {
      try { return JSON.parse(localStorage.getItem("qmes-users-v3") || "[]"); }
      catch (e) { return []; }
    })(),
    ui: {
      currentTab: localStorage.getItem("qmes_current_tab") || "dash",
      openMenu: localStorage.getItem("qmes_open_menu") || "",
      selectedWo: localStorage.getItem("qmes_selected_wo") || "",
    },
  };
  const blob = new Blob([JSON.stringify(payload, null, 2)], { type: "application/json;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  const d = new Date();
  const stamp = `${d.getFullYear()}${String(d.getMonth()+1).padStart(2,"0")}${String(d.getDate()).padStart(2,"0")}_${String(d.getHours()).padStart(2,"0")}${String(d.getMinutes()).padStart(2,"0")}`;
  a.href = url;
  a.download = `QMES_BACKUP_${stamp}.json`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

function restoreQmesBackup() {
  const input = document.createElement("input");
  input.type = "file";
  input.accept = ".json,application/json";
  input.onchange = () => {
    const file = input.files && input.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      try {
        const payload = JSON.parse(String(reader.result || ""));
        if (payload.format !== "QMES_BACKUP_V1" || !payload.data) throw new Error("QMES 백업 파일이 아닙니다.");
        if (!confirm("현재 로컬 데이터를 백업 파일 내용으로 교체할까요?")) return;
        localStorage.setItem(DB_KEY, JSON.stringify({ ...dbDefault(), ...payload.data }));
        if (Array.isArray(payload.users)) localStorage.setItem("qmes-users-v3", JSON.stringify(payload.users));
        if (payload.ui?.currentTab) localStorage.setItem("qmes_current_tab", payload.ui.currentTab);
        if (payload.ui?.openMenu) localStorage.setItem("qmes_open_menu", payload.ui.openMenu);
        if (payload.ui?.selectedWo) localStorage.setItem("qmes_selected_wo", payload.ui.selectedWo);
        alert("복원이 완료되었습니다.");
        location.reload();
      } catch (e) {
        alert(`복원 실패: ${e.message || "파일을 확인하세요."}`);
      }
    };
    reader.readAsText(file, "utf-8");
  };
  input.click();
}

function qmesStart() {
  ReactDOM.createRoot(document.getElementById("root")).render(React.createElement(QMESApp));
}

