function Badge({ tone, children }) {
  const tones = {
    green: "bg-emerald-500/10 text-emerald-400 border-emerald-500/30",
    red: "bg-red-500/10 text-red-400 border-red-500/30",
    amber: "bg-amber-500/10 text-amber-400 border-amber-500/30",
    blue: "bg-sky-500/10 text-sky-400 border-sky-500/30",
    violet: "bg-violet-500/10 text-violet-400 border-violet-500/30",
    gray: "bg-slate-500/10 text-slate-400 border-slate-500/30",
  };
  return (
    <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium border ${tones[tone]}`}>
      {children}
    </span>
  );
}

function Panel({ title, right, children, className = "" }) {
  return (
    <div className={`bg-slate-900 border border-slate-800 rounded-lg ${className}`}>
      {title && (
        <div className="flex items-center justify-between px-4 py-3 border-b border-slate-800 gap-3">
          <h3 className="text-sm font-semibold text-slate-200 tracking-wide">{title}</h3>
          {right}
        </div>
      )}
      <div className="p-4">{children}</div>
    </div>
  );
}

function InspectionSummary({ items }) {
  return (
    <section className="qmes-simple-summary qmes-simple-summary-only">
      <div className="qmes-simple-summary-items" style={{"--summary-count": items.length}}>
        {items.map((item) => (
          <div className="qmes-simple-summary-item" key={item.label}>
            <span className={`qmes-simple-summary-light ${item.tone || "sky"}`} aria-hidden="true"></span>
            <span className="qmes-simple-summary-label">{item.label}</span>
            <div className="qmes-simple-summary-value">
              <strong>{item.value}</strong>
              {item.unit && <small>{item.unit}</small>}
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}

function Kpi({ icon: Icon, label, value, unit, delta, deltaUp, tone = "text-sky-400", animated = false, progressValue, showProgress = false, textOnly = false, caption = "" }) {
  const numeric = Number(String(value).replace(/[^0-9.]/g,"")) || 0;
  const labelKey = String(label || "");
  const calculatedProgress = progressValue !== undefined && progressValue !== null
    ? Number(progressValue)
    : labelKey.includes("합격") ? numeric
    : labelKey.includes("LOT") ? (numeric > 0 ? 100 : 0)
    : labelKey.includes("부적합") || labelKey.includes("반품") ? numeric
    : 58;
  const progress = Math.max(0, Math.min(100, Number.isFinite(calculatedProgress) ? calculatedProgress : 0));
  const [displayProgress, setDisplayProgress] = useState(animated ? 0 : progress);

  useEffect(() => {
    if (!animated) {
      setDisplayProgress(progress);
      return;
    }
    setDisplayProgress(0);
    const timer = window.setTimeout(() => setDisplayProgress(progress), 80);
    return () => window.clearTimeout(timer);
  }, [progress, animated]);

  return (
    <div className={`bg-slate-900 border border-slate-800 rounded-lg ${textOnly ? "qmes-text-kpi-card" : "qmes-hybrid-kpi-card"} ${animated ? "qmes-iqc-kpi-card" : ""}`}>
      {!textOnly && Icon && (
        <div className="qmes-hybrid-donut" style={{"--donut-progress": `${displayProgress}%`}}>
          <div className="qmes-hybrid-ring"></div>
          <div className="qmes-hybrid-ring-inner"></div>
          <Icon className={`qmes-hybrid-icon ${tone}`} />
          {animated && <span className="qmes-hybrid-percent">{Math.round(displayProgress)}%</span>}
        </div>
      )}
      <div className={textOnly ? "qmes-text-kpi-copy" : "qmes-hybrid-copy"}>
        <div className="qmes-hybrid-label-row">
          {animated && <span className={`qmes-iqc-kpi-dot ${tone}`}></span>}
          <span className="qmes-hybrid-label">{label}</span>
        </div>
        <div className="qmes-hybrid-value-row">
          <span className="qmes-hybrid-value">{value}</span>
          {unit && <span className="qmes-hybrid-unit">{unit}</span>}
        </div>
        <div className={textOnly ? "qmes-text-kpi-caption" : "qmes-hybrid-caption"}>
          {caption || (labelKey.includes("합격") && "검사 완료 기준 합격 비율")}
          {!caption && labelKey.includes("LOT") && "이번 달 누적 입고 실적"}
          {!caption && labelKey.includes("부적합") && "즉시 확인이 필요한 항목"}
          {!caption && labelKey.includes("반품") && "공급사 반송 처리 건수"}
        </div>
        {showProgress && (
          <div className="mt-2 h-1.5 w-full overflow-hidden rounded-full bg-slate-800" role="progressbar" aria-label={`${label} 진행률`} aria-valuemin="0" aria-valuemax="100" aria-valuenow={Math.round(progress)}>
            <div className="h-full rounded-full bg-emerald-400 transition-all duration-500" style={{ width: `${displayProgress}%` }} />
          </div>
        )}
        {delta && (
          <div className={`qmes-hybrid-delta ${deltaUp ? "is-up" : "is-down"}`}>
            {deltaUp ? <TrendingUp size={12} /> : <TrendingDown size={12} />}
            <span>{delta} 전일 대비</span>
          </div>
        )}
      </div>
    </div>
  );
}

const chartTooltip = {
  contentStyle: { background: "#0F1E32", border: "1px solid #243D58", borderRadius: 8, fontSize: 12 },
  labelStyle: { color: "#C5D5E8" },
};

